import{_ as s,C as i,o as r,c as n,j as t,a as o,E as h,a5 as d}from"./chunks/framework.-jms6n7v.js";const y=JSON.parse('{"title":"Performance","description":"How fast DaruDB reads and writes next to the embedded databases each of its languages uses most, measured with the benchmark in the repository: the same…","frontmatter":{"title":"Performance","order":3,"aside":false,"pageClass":"performance-page","prev":{"text":"Comparison","link":"/compare"},"next":{"text":"Migration","link":"/migration/"}},"headers":[{"level":2,"title":"What is measured","slug":"what-is-measured","link":"#what-is-measured","children":[]},{"level":2,"title":"How it is kept fair","slug":"how-it-is-kept-fair","link":"#how-it-is-kept-fair","children":[]},{"level":2,"title":"Next to Realm","slug":"next-to-realm","link":"#next-to-realm","children":[]},{"level":2,"title":"Where DaruDB is behind, and why","slug":"where-darudb-is-behind-and-why","link":"#where-darudb-is-behind-and-why","children":[]},{"level":2,"title":"Run it yourself","slug":"run-it-yourself","link":"#run-it-yourself","children":[]}],"relativePath":"performance.md","filePath":"en/performance.md","lastUpdated":1791633183000}'),l={name:"performance.md"};function c(u,e,m,p,f,g){const a=i("PerformanceTable");return r(),n("div",null,[e[0]||(e[0]=t("h1",{id:"performance",tabindex:"-1"},[o("Performance "),t("a",{class:"header-anchor",href:"#performance","aria-label":'Permalink to "Performance"'},"​")],-1)),e[1]||(e[1]=t("p",null,"How fast DaruDB reads and writes next to the embedded databases each of its languages uses most, measured with the benchmark in the repository: the same objects and workloads in every database, at the same durability settings, on one machine.",-1)),e[2]||(e[2]=t("p",null,"The table follows the language chosen in the sidebar. The stores of one language ran on one machine one after another, so their times compare with each other; the tables of different languages come from different runs and do not.",-1)),h(a),e[3]||(e[3]=d(`<h2 id="what-is-measured" tabindex="-1">What is measured <a class="header-anchor" href="#what-is-measured" aria-label="Permalink to &quot;What is measured&quot;">​</a></h2><p>One collection of 100,000 objects, each with a name, an email under a unique index, an age under an index, a city and a score, both without an index. Every row times many operations and divides by their number:</p><table tabindex="0"><thead><tr><th>Workload</th><th>What it does</th></tr></thead><tbody><tr><td>Insert, one object per sync commit</td><td>500 commits of one object, each waiting for the disk</td></tr><tr><td>Insert, one object per deferred commit</td><td>10,000 commits of one object, each leaving the sync for later</td></tr><tr><td>Insert 100,000 objects in one transaction</td><td>Every object, the commit included</td></tr><tr><td>Get by primary key, random order</td><td>100,000 reads of one object</td></tr><tr><td>Get by a unique index, random order</td><td>20,000 reads of one object through the email</td></tr><tr><td>Query an indexed value, 1,250 objects</td><td>The objects of one age</td></tr><tr><td>Query an indexed range, sorted, first 20</td><td>The first 20 objects of five ages, sorted by age descending, then by key</td></tr><tr><td>Count through an index</td><td>The objects with an age of 40 or more</td></tr><tr><td>Query without an index, 1,000 objects</td><td>The objects of one city</td></tr><tr><td>Top 10 by a field without an index</td><td>The 10 objects with the highest score</td></tr><tr><td>Read and update 10,000 objects</td><td>Each read, given a new age and written back, in one transaction with its commit</td></tr><tr><td>Delete 10,000 objects</td><td>In one transaction with its commit</td></tr></tbody></table><p>Every database is used the way an application in that language would use it. DaruDB runs through its public API with a schema, SQLite through SQL with prepared statements, and the key-value stores keep a record and the indexes an application would write for them. Every read is made into an object of the language with all its fields, and a query that runs many times is prepared once. An update sets the one field it changes where the language&#39;s DaruDB package can, as SQL sets one column: through Node.js and Python with <code>update</code>, where writing the whole object back would build it again in the language first, and through Rust and Dart by writing the typed object back.</p><p>The Node.js table also has Realm, for applications moving from it, though its vendor deprecated it in September 2024 and ended support in September 2025; the <a href="./migration/realm">migration guide</a> shows how to move the data. Realm assigns no keys, so the application gives each object the key the other stores assign. It has no unique index besides the primary key, so the email has a plain index, and its queries are strings it parses on every call, since it has no prepared queries. An update sets the one property.</p><h2 id="how-it-is-kept-fair" tabindex="-1">How it is kept fair <a class="header-anchor" href="#how-it-is-kept-fair" aria-label="Permalink to &quot;How it is kept fair&quot;">​</a></h2><ul><li><strong>The same durability.</strong> A sync commit waits until the disk has it: DaruDB&#39;s default commit, SQLite&#39;s write-ahead log with <code>synchronous = FULL</code>, LMDB&#39;s default commit, redb&#39;s <code>Durability::Immediate</code>, Hive&#39;s write followed by <code>flush</code>, and Realm&#39;s commit. A deferred commit returns before that: DaruDB&#39;s deferred commit, <code>synchronous = NORMAL</code>, LMDB&#39;s <code>NO_SYNC</code>, redb&#39;s <code>Durability::None</code> and Hive&#39;s write alone. Realm has no commit that leaves the sync for later, so its cell in that row is empty. redb&#39;s promises less than the others, since nothing it writes is durable until a later immediate commit.</li><li><strong>The same work.</strong> Every row hashes the keys and ages of what it found, in the order it found them, and a run in which two databases disagree fails rather than giving a time.</li><li><strong>A clean start.</strong> Each pass of each database runs in a process of its own, on new files, and the databases take turns in an order that changes every run. A time is the median of the runs.</li><li><strong>The same machine.</strong> The databases of one language run on one machine, one after another.</li></ul><p>The cache each database may use is left at its default, apart from SQLite&#39;s, which is raised to DaruDB&#39;s 32 MiB. A database that keeps every object in memory, as Hive does, reads without touching its file.</p><p>The tables come from the <code>run-benchmarks</code> workflow, which runs each language on a GitHub-hosted Linux runner of its own. Those runners mount their disk without write barriers, so a sync commit there waits for the file system&#39;s work but not for the disk&#39;s own cache. They also differ in processor and disk from one run to the next, and the commit rows move most with them: through Node.js, a deferred commit of one object took SQLite 68 µs and DaruDB 34 µs on the runner of one run, and 34 µs and 46 µs on that of the next. The next section says why. Compare a commit row&#39;s databases within one table only.</p><h2 id="next-to-realm" tabindex="-1">Next to Realm <a class="header-anchor" href="#next-to-realm" aria-label="Permalink to &quot;Next to Realm&quot;">​</a></h2><p>For an application moving from Realm, the Node.js table is the one to read; choose Node.js in the sidebar to see it. DaruDB is ahead of Realm in every row but the query of a field without an index, where Realm, which keeps each property&#39;s values together, reads only the city and takes 0.62 times DaruDB&#39;s time. Realm takes 2.2 times as long for a sync commit and has no deferred one, 6.3 times as long to insert 100,000 objects in one transaction, and 6.8 times to delete 10,000. It takes 3.6 times as long to read by key, and 13 times through the email, since it parses a query string on every call and has no unique index besides the primary key. It takes 4.6 times as long for the objects of one age, and 110 times for the first 20 of five ages, since it sorts every object of the five ages before it takes the first 20. An update takes about as long in both, since both set one field.</p><h2 id="where-darudb-is-behind-and-why" tabindex="-1">Where DaruDB is behind, and why <a class="header-anchor" href="#where-darudb-is-behind-and-why" aria-label="Permalink to &quot;Where DaruDB is behind, and why&quot;">​</a></h2><p>DaruDB is ahead of every other database in most rows in Node.js, Dart and Python. In Rust, LMDB is ahead in the deferred commit, the reads and the queries, and redb in the reads by key and the queries through the age index. These are the rows where DaruDB is not ahead, with what makes each slower:</p><ul><li><strong>Sync commits</strong> move from pass to pass more than any other row, and their order changes with the runner: SQLite is 13 to 18% ahead in Node.js and Python, while DaruDB is ahead in Rust and Dart. On the runners, a sync commit is mostly the file system&#39;s work. DaruDB writes a commit&#39;s pages where the free pages are, scattered over the file, with a write call for each run of them, where SQLite appends its pages to its log.</li><li><strong>A deferred commit of one object.</strong> LMDB is ahead in every language it runs in. On Linux, about half of DaruDB&#39;s commit is spent in the kernel: it makes about fourteen system calls, ten writes for the eleven or so pages it writes and four to take and release the writer lock and to check for other writers and readers, since processes coordinate through file locks alone. LMDB makes seven writes and coordinates processes through a mutex in shared memory, which DaruDB rejects: a process that dies holding one can leave the others stuck. SQLite is ahead in Node.js and Python, whose runners had AMD EPYC 7763 processors this time; on the other kinds of runner, DaruDB&#39;s deferred commit took half of SQLite&#39;s time or less. SQLite&#39;s deferred commits are not all of its work: it syncs its log and its file at each checkpoint of the log, every thousand pages, and on most runners its deferred commits spent two thirds of their time or more waiting for those syncs. The EPYC 7763 runners finish them sooner, and their processor, the oldest of the runner kinds, is the slowest at DaruDB&#39;s commit, which waits for nothing.</li><li><strong>Reads and queries through an index, in Rust.</strong> LMDB and redb find an object by its key faster, LMDB finds one by its email faster, and both run the queries through the age index faster. A DaruDB lookup finds each page it passes through in its page cache, under a lock and with a reference count, which takes a larger share of a lookup on these x86 processors than on Apple&#39;s, then searches the node comparing keys as bytes, and decodes the record, which tags each field with an id, into the struct. LMDB reads its file through a memory map, with no cache to look in, redb compares its primary keys as integers, and both read the record written by hand for them, with its fields at fixed places. DaruDB does not map its file, because another process can change mapped bytes under a reader, and a mapping does not mix with encryption. The sorted range costs more besides: it sorts by age descending and then by key, so DaruDB walks the age index backwards and holds back the objects of each age to give them in key order, where the loop written for the key-value stores asks for each age in turn. On an Apple M1 Max, DaruDB was ahead of LMDB in these rows but the sorted range.</li><li><strong>Queries without an index.</strong> LMDB in Rust scans several times faster, Realm in Node.js finds the objects of one city 1.6 times as fast, and SQLite is 6 to 16% faster in Rust, Node.js and Dart. The record written by hand for the key-value stores keeps the age and the score at fixed places, so a scan reads those bytes and decodes only what it returns; Realm keeps each property&#39;s values together, so a scan reads only the city; and SQLite&#39;s record lists the types of its columns at its start, so finding one column adds up the sizes before it without reading them. A DaruDB record tags each field with an id and a type, which makes renaming a field free and lets the engine check what it reads from a file it does not trust, so a scan steps over the fields before the one it tests, and it reads each leaf through the page cache. On other kinds of runner, redb in Rust and Hive in Dart scanned faster as well.</li><li><strong>A lookup through a unique index in Node.js</strong>, where SQLite is 11% ahead: the first lookup that reaches a page of an index loads the page, checks it and works out the heads of its keys.</li><li><strong>Rows within 8% either way</strong>, such as LMDB&#39;s lookups through the email index in Python and SQLite&#39;s sorted range in Rust and its query of one age in Python, are within what one run moves on a shared runner.</li></ul><h2 id="run-it-yourself" tabindex="-1">Run it yourself <a class="header-anchor" href="#run-it-yourself" aria-label="Permalink to &quot;Run it yourself&quot;">​</a></h2><p>The harness is in <a href="https://github.com/jooy2/darudb/tree/main/bench" target="_blank" rel="noreferrer"><code>bench/</code></a> of the repository, with a README that lists every setting. The <code>run-benchmarks</code> workflow runs it on GitHub-hosted runners and opens a pull request with the results for this page.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench/rust</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../..</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench/run.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --runs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench/results/rust.json</span></span></code></pre></div>`,17))])}const k=s(l,[["render",c]]);export{y as __pageData,k as default};
